/**
 * Fixture builders for untrusted upload tests.
 *
 * Everything here is generated by hand so tests do not depend on binary files
 * or on the parsers under test: a "PDF" is assembled object by object, and a
 * "DOCX" is a real zip archive written byte by byte.
 */
import zlib from "node:zlib";

const pdfString = (value) => String(value).replace(/([\\()])/g, "\\$1");

/**
 * Assemble a small but structurally valid PDF.
 *
 * @param {object} options
 * @param {number} [options.pages]     page count
 * @param {string} [options.text]      text drawn on each page
 * @param {boolean} [options.encrypt]  add an /Encrypt trailer entry
 * @param {boolean} [options.noText]   pages with empty content streams
 * @param {number} [options.ops]       repeat a text-showing operator this often
 * @param {number} [options.truncate]  drop this many trailing bytes
 */
export const buildPdf = ({ pages = 1, text = "Hello", encrypt = false, noText = false, ops = 0, truncate = 0 } = {}) => {
  const objects = {};
  const pageIds = [];
  let nextId = 3;

  for (let index = 0; index < pages; index += 1) {
    pageIds.push({ page: nextId, content: nextId + 1 });
    nextId += 2;
  }
  const fontId = nextId;
  nextId += 1;
  const encryptId = encrypt ? nextId : null;

  objects[1] = "<</Type/Catalog/Pages 2 0 R>>";
  objects[2] = `<</Type/Pages/Kids[${pageIds.map((ids) => `${ids.page} 0 R`).join(" ")}]/Count ${pages}>>`;

  pageIds.forEach((ids, index) => {
    objects[ids.page] =
      `<</Type/Page/Parent 2 0 R/MediaBox[0 0 300 200]` +
      `/Resources<</Font<</F1 ${fontId} 0 R>>>>/Contents ${ids.content} 0 R>>`;

    let stream;
    let filter = "";
    if (noText) stream = "";
    else if (ops > 0) {
      // Deflate the operator soup so the file stays small on the wire while the
      // parser still has to execute every operator.
      stream = zlib.deflateSync(Buffer.from(`BT /F1 8 Tf ${"20 20 Td (aaaaaaaaaaaaaaaa) Tj ".repeat(ops)}ET`)).toString("latin1");
      filter = "/Filter/FlateDecode";
    } else stream = `BT /F1 12 Tf 20 100 Td (${pdfString(text)} page ${index + 1}) Tj ET`;
    objects[ids.content] = `<</Length ${stream.length}${filter}>>\nstream\n${stream}\nendstream`;
  });

  objects[fontId] = "<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>";
  if (encryptId) {
    const key = `<${"AB".repeat(32)}>`;
    objects[encryptId] = `<</Filter/Standard/V 1/R 2/O ${key}/U ${key}/P -1/Length 40>>`;
  }

  let out = "%PDF-1.4\n";
  const offsets = [];
  const size = Math.max(...Object.keys(objects).map(Number)) + 1;
  for (let id = 1; id < size; id += 1) {
    offsets.push(out.length);
    out += `${id} 0 obj\n${objects[id]}\nendobj\n`;
  }

  const xrefStart = out.length;
  out += `xref\n0 ${size}\n0000000000 65535 f \n`;
  for (const offset of offsets) out += `${String(offset).padStart(10, "0")} 00000 n \n`;
  out += `trailer\n<</Size ${size}/Root 1 0 R${encryptId ? `/Encrypt ${encryptId} 0 R` : ""}>>\n`;
  out += `startxref\n${xrefStart}\n%%EOF\n`;

  const buffer = Buffer.from(out, "latin1");
  return truncate > 0 ? buffer.subarray(0, Math.max(0, buffer.length - truncate)) : buffer;
};

let crcTable = null;
const crc32 = (buffer) => {
  if (!crcTable) {
    crcTable = new Int32Array(256);
    for (let index = 0; index < 256; index += 1) {
      let value = index;
      for (let bit = 0; bit < 8; bit += 1) {
        value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
      }
      crcTable[index] = value;
    }
  }
  let crc = -1;
  for (const byte of buffer) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ -1) >>> 0;
};

/**
 * Write a zip archive. `declaredSize` lets a test lie about how much a
 * compressed entry expands to, which is exactly what a zip bomb does.
 */
export const buildZip = (entries) => {
  const localParts = [];
  const centralParts = [];
  let offset = 0;

  for (const entry of entries) {
    const name = Buffer.from(entry.name, "utf8");
    const data = Buffer.isBuffer(entry.data) ? entry.data : Buffer.from(String(entry.data), "utf8");
    const compressed = zlib.deflateRawSync(data);
    const declared = entry.declaredSize ?? data.length;

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0, 6);
    local.writeUInt16LE(8, 8);
    local.writeUInt16LE(0, 10);
    local.writeUInt16LE(0, 12);
    local.writeUInt32LE(crc32(data), 14);
    local.writeUInt32LE(compressed.length, 18);
    local.writeUInt32LE(declared & 0xffffffff, 22);
    local.writeUInt16LE(name.length, 26);
    local.writeUInt16LE(0, 28);
    localParts.push(local, name, compressed);

    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(0, 8);
    central.writeUInt16LE(8, 10);
    central.writeUInt16LE(0, 12);
    central.writeUInt16LE(0, 14);
    central.writeUInt32LE(crc32(data), 16);
    central.writeUInt32LE(compressed.length, 20);
    central.writeUInt32LE(declared & 0xffffffff, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt16LE(0, 30);
    central.writeUInt16LE(0, 32);
    central.writeUInt16LE(0, 34);
    central.writeUInt16LE(0, 36);
    central.writeUInt32LE(0, 38);
    central.writeUInt32LE(offset, 42);
    centralParts.push(central, name);

    offset += local.length + name.length + compressed.length;
  }

  const centralDirectory = Buffer.concat(centralParts);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(centralDirectory.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...localParts, centralDirectory, eocd]);
};

const DOCUMENT_XML = (text) =>
  `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
  `<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">` +
  `<w:body><w:p><w:r><w:t>${text}</w:t></w:r></w:p></w:body></w:document>`;

/** A minimal but real DOCX that mammoth can read. */
export const buildDocx = ({ text = "Hello from a DOCX resume" } = {}) =>
  buildZip([
    {
      name: "[Content_Types].xml",
      data:
        `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
        `<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
        `<Default Extension="xml" ContentType="application/xml"/>` +
        `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>` +
        `<Override PartName="/word/document.xml" ` +
        `ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>` +
        `</Types>`
    },
    {
      name: "_rels/.rels",
      data:
        `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>` +
        `<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">` +
        `<Relationship Id="rId1" ` +
        `Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" ` +
        `Target="word/document.xml"/></Relationships>`
    },
    { name: "word/document.xml", data: DOCUMENT_XML(text) }
  ]);

/** A DOCX whose central directory claims a huge expansion. */
export const buildDocxBomb = ({ declaredSize = 900 * 1024 * 1024 } = {}) =>
  buildZip([
    { name: "word/document.xml", data: DOCUMENT_XML("bomb"), declaredSize }
  ]);

/** Patch a zip EOCD record to advertise more entries than it contains. */
export const patchZipEntryCount = (zip, count) => {
  const copy = Buffer.from(zip);
  const eocd = copy.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  if (eocd === -1) throw new Error("no EOCD in fixture");
  copy.writeUInt16LE(count, eocd + 10);
  return copy;
};
